pragma solidity ^0.8.20;

// contract NonPayableReceiverVul {

//     /*
//         TRACK EXECUTION
//     */
//     uint256 public counter;

//     /*
//     =====================================================
//     NORMAL FUNCTION
//     =====================================================

//     NOT payable.
//     */

//     function increment()
//         external
