// =========================================================
// SENDER CONTRACT
// =========================================================
// */

// contract ETHSenderVul {

//     /*
//         TRACK LAST RESULT
//     */
//     bool public lastSuccess;

//     /*
//         TRACK TOTAL SENT
//     */
//     uint256 public totalSent;

//     /*
//     =====================================================
//     SEND ETH SAFELY
//     =====================================================
//     */

//     function sendETH(
//         address payable _receiver
//     )
//         external
//         payable
//     {

//         /*
//             Attempt ETH transfer using call().
//         */
//         (bool success, ) =
//             _receiver.call{
//                 value: msg.value
//             }("");

//         /*
//             Save result.
//         */
//         lastSuccess = success;

//         /*
//             SAFE HANDLING.

//             Revert if transfer failed.
//         */
//         require(
//             success,
//             "ETH transfer failed"
//         );

//         /*
//             Update accounting ONLY after success.
//         */
//         totalSent += msg.value;
//     }

//     /*
//     =====================================================
//     DANGEROUS SEND
//     =====================================================

//     Ignores success boolean.
//     */

//     function dangerousSend(
//         address payable _receiver
//     )
//         external
//         payable
//     {

//         /*
//             Attempt ETH transfer.
//         */
//         _receiver.call{
//             value: msg.value
//         }("");

//         /*
//             DANGEROUS:
//             Execution continues even if transfer failed.
//         */

//         totalSent += msg.value;
//     }

//     /*
//     =====================================================
//     CHECK CONTRACT BALANCE
//     =====================================================
